//! Shared client fixture for isolated facade feature manifests generated by the runner.
//!
//! Fixture features describe expected imports; they do not enable dependency features.

#![warn(clippy::all, clippy::pedantic)]
// Exact literals check CPU value round trips, not approximate DSP output.
#![allow(clippy::float_cmp)]

#[cfg(feature = "graphics")]
#[test]
fn default_graphics_paths_remain_available_without_initialization() {
    let color = vmnl::common::Rgba::RED;
    let point = vmnl::d2::Vector2f { x: 1.0, y: 2.0 };
    assert_eq!(color.r, 255);
    assert_eq!((point.x, point.y), (1.0, 2.0));
    let _: fn() -> vmnl::VMNLResult<vmnl::Context> = vmnl::Context::new;
    let _ = std::any::type_name::<vmnl::Window>();
}

#[cfg(feature = "audio")]
#[test]
fn audio_types_are_the_domain_types_and_default_to_manual_control() {
    use vmnl::audio::{AudioConfig, AudioDevice, AudioDeviceBuilder, ControlMode};
    let config: AudioConfig = vmnl_audio::AudioConfig::default();
    assert_eq!(config.sample_rate(), 44_100);
    assert_eq!(AudioDevice::builder().control_mode(), ControlMode::Manual);
    assert_eq!(
        AudioDeviceBuilder::default().control_mode(),
        ControlMode::Manual
    );
    assert_eq!(
        AudioDevice::builder().thread(true).control_mode(),
        ControlMode::Automatic
    );
    assert_eq!(
        AudioDevice::builder()
            .thread(true)
            .thread(false)
            .control_mode(),
        ControlMode::Manual
    );
    let _: fn(&AudioDevice) -> ControlMode = AudioDevice::control_mode;
    let _: fn(AudioConfig) -> vmnl::audio::AudioResult<AudioDevice> = AudioDevice::new;
}

#[cfg(feature = "audio")]
#[test]
fn invalid_audio_configuration_fails_before_opening_a_device() {
    use vmnl::audio::{AudioDevice, AudioError};
    assert!(matches!(
        AudioDevice::builder().sample_rate(0).build(),
        Err(AudioError::InvalidState(_))
    ));
    assert!(matches!(
        AudioDevice::builder().channels(1).build(),
        Err(AudioError::UnsupportedFormat(_))
    ));
}

#[cfg(feature = "audio")]
#[test]
fn audio_playback_configuration_and_state_are_exposed_without_graphics() {
    use vmnl::audio::{AudioError, MusicPlayConfig, PlaybackState, SoundPlayConfig};
    assert_eq!(SoundPlayConfig::default().volume, 1.0);
    assert!(!MusicPlayConfig::default().looping);
    assert_ne!(PlaybackState::Playing, PlaybackState::Stopped);
    assert!(AudioError::InvalidState("fixture".to_owned())
        .to_string()
        .contains("fixture"));
}
